//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn character_substring_real_proto_all_native_kinds_owners_and_exact_utf16_boundaries(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var read=CharacterData.prototype.substringData,d=Object.getOwnPropertyDescriptor(CharacterData.prototype,'substringData');if(read.name!=='substringData'||read.length!==2||!d.enumerable||!d.writable||!d.configurable||Object.hasOwn(Text.prototype,'substringData'))throw 'canonical CharacterData descriptor';var xml=document.implementation.createDocument(null,''),generic=new Document(),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument,html=document.implementation.createHTMLDocument('owner');for(var owner of [document,html,xml,generic,template]){var value='A\ud83d\ude00B\ud800C',nodes=[owner.createTextNode(value),owner.createComment(value),owner.createProcessingInstruction('target',value)];if(owner===xml||owner===generic||owner===template)nodes.push(owner.createCDATASection(value));for(var node of nodes){var before=node.data;if(node.substringData(1,2)!=='\ud83d\ude00'||read.call(node,1,1).charCodeAt(0)!==0xd83d||node.substringData(2,1).charCodeAt(0)!==0xde00||node.substringData(4,1).charCodeAt(0)!==0xd800||node.substringData(3,999)!=='B\ud800C'||node.substringData(6,99)!==''||node.substringData(0,0)!==''||node.data!==before||node.ownerDocument!==owner)throw 'exact UTF16 query and immutable genuine data';}}
for(var bad of [document,document.body,document.createAttribute('x'),{},CharacterData.prototype,null]){var calls=0,caught=false;try{read.call(bad,{valueOf:function(){calls++;return 0;}},1);}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before author conversion';}var caught=false;try{read.call(document.createTextNode('held'),0);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'two required arguments';
"#);
}
#[test]
fn character_substring_unsigned_long_wrap_nonfinite_truncate_clamp_and_typed_index_error(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var node=document.createTextNode('abcd');if(node.substringData(4294967297.9,2.9)!=='bc'||node.substringData(-4294967296,2)!=='ab'||node.substringData(NaN,Infinity)!==''||node.substringData(Infinity,2)!=='ab'||node.substringData(undefined,2)!=='ab'||node.substringData(null,undefined)!==''||node.substringData(1,-1)!=='bcd'||node.substringData(4,4294967295)!=='')throw 'WebIDL unsigned long semantics';for(var offset of [5,-1,4294967295]){var caught=false;try{node.substringData(offset,0);}catch(e){caught=e instanceof DOMException&&e.name==='IndexSizeError'&&e.code===1;}if(!caught)throw 'typed offset error after unsigned conversion';}for(var bad of [Symbol('offset'),1n]){var caught=false;try{node.substringData(bad,1);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'ToNumber rejects symbol and BigInt';}
"#);
}
#[test]
fn character_substring_converts_both_numbers_before_current_data_validation_and_keeps_effects(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var node=document.createTextNode('old'),trace='',watch=new MutationObserver(function(){});watch.observe(node,{characterData:true});var offset={valueOf:function(){trace+='offset|';return 2;}},count={valueOf:function(){trace+='count|';node.data='x';return 1;}},caught=false;try{node.substringData(offset,count);}catch(e){caught=e instanceof DOMException&&e.name==='IndexSizeError';}if(!caught||trace!=='offset|count|'||node.data!=='x'||watch.takeRecords().length!==1)throw 'conversion effects precede native bounds read';trace='';var sentinel={error:'author'},seen=null;try{node.substringData({valueOf:function(){trace+='offset|';return 99;}},{valueOf:function(){trace+='count|';throw sentinel;}});}catch(e){seen=e;}if(seen!==sentinel||trace!=='offset|count|'||node.data!=='x')throw 'author count conversion exception precedes offset validation';var current=node.substringData(1,{valueOf:function(){node.data='expanded';return 3;}});if(current!=='xpa'||node.data!=='expanded'||watch.takeRecords().length!==1)throw 'reads current data after count conversion';");
}
#[test]
fn character_substring_queries_preserve_live_ranges_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var text=document.createTextNode('A\ud83d\ude00B\ud800C'),root=document.createElement('span');root.appendChild(text);var range=document.createRange();range.setStart(text,2);range.setEnd(text,5);var watch=new MutationObserver(function(){});watch.observe(text,{characterData:true,characterDataOldValue:true});for(var i=0;i<10;i++){if(text.substringData(1,2)!=='\ud83d\ude00'||text.substringData(4,1).charCodeAt(0)!==0xd800)throw 'query result';}if(range.startContainer!==text||range.endContainer!==text||range.startOffset!==2||range.endOffset!==5||watch.takeRecords().length||text.parentNode!==root||text.data!=='A\ud83d\ude00B\ud800C')throw 'query does not mutate range data topology or observations';"#);
}
#[test]
fn character_substring_saved_child_method_origin_precedes_numeric_author_conversion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.CharacterData.prototype.substringData,node=document.createTextNode('held'),calls=0,offset={valueOf:function(){calls++;return 1;}},count={valueOf:function(){calls++;return 2;}};if(saved.call(node,offset,count)!=='el'||calls!==2)throw 'genuine captured CharacterData reader';");page.set_location(&crate::navigation::address("https://other-character-substring.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(node,offset,count);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==2||node.data!=='held')throw 'origin before numeric conversion';");
}
